/** An immutable record of a single quantity change, including the level state it produced. */ export type InventoryMovement = { /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "committed_quantity_delta": string; /** RFC3339 timestamp. Format: date-time. */ "created_at": string; "created_by": string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "damaged_quantity_delta": string; "external_actor_id"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "held_quantity_delta": string; "idempotency_key"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "incoming_quantity_delta": string; /** The inventory item this movement is about. Present only when the list request asked for expand=inventory_item. */ "inventory_item"?: InventoryItem; "inventory_item_id": string; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "inventory_level_claim_revision": string; "inventory_level_id": string; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "inventory_level_physical_revision": string; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "inventory_level_revision": string; "inventory_movement_id": string; "location_id": string; "note"?: string; /** RFC3339 timestamp. Format: date-time. */ "occurred_at": string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "on_hand_quantity_delta": string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "quality_control_quantity_delta": string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "quarantined_quantity_delta": string; "reason": "commit" | "condition_changed" | "consume" | "damage" | "damaged" | "depart" | "fulfillment_canceled" | "fulfillment_handoff" | "loss" | "lost" | "manual_correction" | "other" | "owner_deadline_reached" | "physical_count" | "quality_control" | "quarantined" | "reallocation" | "receive" | "received_stock" | "release" | "report_loss" | "return_to_origin" | "route_and_hold" | "safety_stock_change" | "sellable" | "theft" | (string & {}); "resulting_inventory_level": InventoryLevel; "return_disposition_id"?: string; "return_id"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "safety_stock_quantity_delta": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "source_observation_sequence"?: string; "source_reference"?: InventorySourceReference; "source_system": (({ "external_source_id"?: string; "type": "manual" | "pos" | "wms" | "erp" | "flint" | "other" | (string & {}); }) | (null)); "type": "adjustment" | "count_applied" | "fulfillment_consumed" | "reservation_committed" | "reservation_commitment_released" | "reservation_expired" | "reservation_held" | "reservation_hold_released" | "reservation_reallocated_in" | "reservation_reallocated_out" | "return_received" | "safety_stock_change" | "system_correction" | "transfer_departed" | "transfer_received" | "transfer_returned" | "transfer_lost" | (string & {}); };
